package domain

import (
	"bytes"
	"crypto/ed25519"
	"crypto/sha256"
	"encoding/binary"
	"encoding/json"
	"errors"
	"fmt"
	"sort"
	"strconv"
	"time"

	"github.com/letwir/paddock/internal/canonical"
)

var ErrInvalidApproval = errors.New("invalid safety approval")

type SafetyAction string

const (
	SafetyActionStop       SafetyAction = "EMERGENCY_STOP"
	SafetyActionRelease    SafetyAction = "RELEASE"
	SafetyActionHoldExtend SafetyAction = "HOLD_EXTEND"
)

// SafetySigner is an externally provisioned PoC identity. No private key is
// accepted or generated by this package.
type SafetySigner struct {
	ID        string
	PublicKey []byte
}

// HoldExtendApprovalMessage is the HOLD_EXTEND variant of the human safety
// protocol. Stop/Release retain their existing signing bytes. HoldUsed binds the
// persisted closed-episode total; HoldSince and HoldDeadline bind the entire open
// episode, so verification can use a later DB observation without resigning.
// Command ID/nonce replay fencing across transactions remains Application's job;
// the one-shot ExtensionUsed bit rejects reuse against the returned Domain state.
func HoldExtendApprovalMessage(r PolicyRollout, expectedEpoch Epoch, commandID, nonce string, newCap time.Duration) ([]byte, error) {
	m := r.Monitoring
	if r.Validate() != nil || r.State != RolloutMonitoring || m.Validate() != nil || m.Decision != DecisionHold || m.ExtensionUsed || expectedEpoch != r.BaseSecurityEpoch || validateID(commandID) != nil || validateID(nonce) != nil || newCap != MonitoringExtendedCap {
		return nil, ErrInvalidApproval
	}
	payload := map[string]any{
		"action": SafetyActionHoldExtend, "scope": r.Scope, "rollout_id": r.ID,
		"security_epoch": expectedEpoch, "hold_used": m.HoldUsed.String(),
		"hold_budget": m.HoldBudget.String(), "new_cap": newCap.String(),
		"extension_used":       m.ExtensionUsed,
		"hold_since":           m.HoldSince.UTC().Format(time.RFC3339Nano),
		"hold_deadline":        m.HoldDeadline.UTC().Format(time.RFC3339Nano),
		"started_at":           m.StartedAt.UTC().Format(time.RFC3339Nano),
		"observation_deadline": m.ObservationDeadline.UTC().Format(time.RFC3339Nano),
		"last_observed_at":     m.LastObservedAt.UTC().Format(time.RFC3339Nano),
		"decision_at":          m.DecisionAt.UTC().Format(time.RFC3339Nano),
		"evidence_digest":      m.EvidenceDigest,
		// Like ActivationCertificate, encode a decimal string to bind every
		// int64 exactly despite JCS's IEEE-754 safe-integer restriction.
		"decision_revision": strconv.FormatInt(m.DecisionRevision, 10),
	}
	encoded, err := json.Marshal(payload)
	if err != nil {
		return nil, ErrInvalidApproval
	}
	codec := canonical.NewJCSCodec()
	canonicalPayload, err := codec.CanonicalizeJSON(encoded)
	if err != nil {
		return nil, ErrInvalidApproval
	}
	msg, err := canonical.Envelope(codec, canonical.DomainApproval, canonical.Context{
		SchemaVersion: "paddock.approval/1", Audience: "governance", RequestID: commandID, Nonce: nonce,
	}, canonicalPayload)
	if err != nil {
		return nil, ErrInvalidApproval
	}
	return msg, nil
}

// HoldExtend authenticates against the current AuthorityState and locked rollout
// snapshot. It raises the TOTAL cap once (not an extra per-episode allowance),
// without changing authority, epochs, observation time, or any input maps.
func (q SafetyQuorum) HoldExtend(state AuthorityState, r PolicyRollout, expectedEpoch Epoch, commandID, nonce string, newCap time.Duration, signatures []SafetySignature, dbNow time.Time) (PolicyRollout, error) {
	dbNow = dbNow.Round(0).UTC()
	if !state.DatabaseAvailable {
		return r, ErrDatabaseUnavailable
	}
	if state.Mode != ScopeActive || state.SecurityEpoch != expectedEpoch || checkRolloutState(state, r, RolloutMonitoring) != nil || monitoringInput(r, dbNow) != nil || r.Monitoring.expired(dbNow) {
		return r, ErrInvalidApproval
	}
	msg, err := HoldExtendApprovalMessage(r, expectedEpoch, commandID, nonce, newCap)
	if err != nil {
		return r, err
	}
	if err := q.verifySignatures(msg, signatures); err != nil {
		return r, err
	}
	out := r
	m := &out.Monitoring
	m.HoldBudget, m.ExtensionUsed = newCap, true
	m.ExtensionCommandID, m.ExtensionNonce = commandID, nonce
	m.HoldDeadline = m.HoldSince.Add(newCap - m.HoldUsed)
	m.LastObservedAt = dbNow
	if out.Validate() != nil {
		return r, ErrInvalidApproval
	}
	return out, nil
}

type SafetyQuorum struct{ signers map[string]ed25519.PublicKey }

// NewSafetyQuorum accepts exactly three distinct IDs and 32-byte Ed25519 public keys.
func NewSafetyQuorum(signers []SafetySigner) (SafetyQuorum, error) {
	if len(signers) != 3 {
		return SafetyQuorum{}, fmt.Errorf("%w: exactly three signers required", ErrInvalidApproval)
	}
	q := SafetyQuorum{signers: make(map[string]ed25519.PublicKey, 3)}
	for _, s := range signers {
		if err := validateID(s.ID); err != nil || len(s.PublicKey) != ed25519.PublicKeySize {
			return SafetyQuorum{}, fmt.Errorf("%w: malformed signer", ErrInvalidApproval)
		}
		if _, ok := q.signers[s.ID]; ok {
			return SafetyQuorum{}, fmt.Errorf("%w: duplicate signer ID", ErrInvalidApproval)
		}
		for _, key := range q.signers {
			if bytes.Equal(key, s.PublicKey) {
				return SafetyQuorum{}, fmt.Errorf("%w: duplicate signer key", ErrInvalidApproval)
			}
		}
		q.signers[s.ID] = append(ed25519.PublicKey(nil), s.PublicKey...)
	}
	return q, nil
}

type SafetySignature struct {
	SignerID  string
	Signature []byte
}

// SafetyApprovalMessage exposes signing bytes only; it never signs and contains
// no private-key capability. The optional activation digest is required for release.
func SafetyApprovalMessage(action SafetyAction, scope ScopeID, expectedEpoch Epoch, commandID, nonce string, activationDigest ...[32]byte) ([]byte, error) {
	if action != SafetyActionStop && action != SafetyActionRelease {
		return nil, fmt.Errorf("%w: unknown action", ErrInvalidApproval)
	}
	if scope.Validate() != nil || validateID(commandID) != nil || validateID(nonce) != nil {
		return nil, fmt.Errorf("%w: invalid scope, command ID, or nonce", ErrInvalidApproval)
	}
	if action == SafetyActionRelease && len(activationDigest) != 1 || action == SafetyActionStop && len(activationDigest) != 0 {
		return nil, fmt.Errorf("%w: activation binding mismatch", ErrInvalidApproval)
	}
	payload := struct {
		Action           SafetyAction `json:"action"`
		Scope            ScopeID      `json:"scope"`
		SecurityEpoch    Epoch        `json:"security_epoch"`
		ActivationDigest string       `json:"activation_digest,omitempty"`
	}{Action: action, Scope: scope, SecurityEpoch: expectedEpoch}
	if action == SafetyActionRelease {
		payload.ActivationDigest = fmt.Sprintf("%x", activationDigest[0])
	}
	encoded, err := json.Marshal(payload)
	if err != nil {
		return nil, fmt.Errorf("%w: encode payload", ErrInvalidApproval)
	}
	codec := canonical.NewJCSCodec()
	canonicalPayload, err := codec.CanonicalizeJSON(encoded)
	if err != nil {
		return nil, fmt.Errorf("%w: canonicalize payload", ErrInvalidApproval)
	}
	message, err := canonical.Envelope(codec, canonical.DomainApproval, canonical.Context{
		SchemaVersion: "paddock.approval/1", Audience: "governance", RequestID: commandID, Nonce: nonce,
	}, canonicalPayload)
	if err != nil {
		return nil, fmt.Errorf("%w: construct envelope", ErrInvalidApproval)
	}
	return message, nil
}

// ActivationDigest deterministically binds every AuthorityState field. Root entries
// are sorted by ID; the encoding is versioned and domain-separated before SHA-256.
func ActivationDigest(s AuthorityState) ([32]byte, error) {
	if err := s.Validate(); err != nil {
		return [32]byte{}, fmt.Errorf("%w: malformed activation", ErrInvalidApproval)
	}
	b := []byte("PADDOCK-AUTHORITY-ACTIVATION\x00v1\x00")
	put := func(v string) {
		var n [4]byte
		binary.BigEndian.PutUint32(n[:], uint32(len(v)))
		b = append(b, n[:]...)
		b = append(b, v...)
	}
	put(string(s.Scope))
	var n [8]byte
	binary.BigEndian.PutUint64(n[:], uint64(s.ScopeActivationEpoch))
	b = append(b, n[:]...)
	binary.BigEndian.PutUint64(n[:], uint64(s.SecurityEpoch))
	b = append(b, n[:]...)
	put(string(s.Mode))
	if s.DatabaseAvailable {
		b = append(b, 1)
	} else {
		b = append(b, 0)
	}
	ids := make([]string, 0, len(s.Roots))
	for id := range s.Roots {
		ids = append(ids, string(id))
	}
	sort.Strings(ids)
	binary.BigEndian.PutUint32(n[:4], uint32(len(ids)))
	b = append(b, n[:4]...)
	for _, raw := range ids {
		id := RootID(raw)
		r := s.Roots[id]
		put(raw)
		put(string(r.Policy.Digest))
		if r.Policy.SafeBaseline {
			b = append(b, 1)
		} else {
			b = append(b, 0)
		}
		binary.BigEndian.PutUint64(n[:], uint64(r.AuthorizationEpoch))
		b = append(b, n[:]...)
	}
	return sha256.Sum256(b), nil
}

func (q SafetyQuorum) verify(state AuthorityState, action SafetyAction, expectedEpoch Epoch, commandID, nonce string, digest *[32]byte, signatures []SafetySignature) error {
	if !state.DatabaseAvailable {
		return ErrDatabaseUnavailable
	}
	if err := state.Validate(); err != nil {
		return fmt.Errorf("%w: invalid authority state", ErrInvalidApproval)
	}
	if state.SecurityEpoch != expectedEpoch {
		return fmt.Errorf("%w: security epoch mismatch", ErrInvalidApproval)
	}
	var msg []byte
	var err error
	if digest == nil {
		msg, err = SafetyApprovalMessage(action, state.Scope, expectedEpoch, commandID, nonce)
	} else {
		msg, err = SafetyApprovalMessage(action, state.Scope, expectedEpoch, commandID, nonce, *digest)
	}
	if err != nil {
		return err
	}
	return q.verifySignatures(msg, signatures)
}

func (q SafetyQuorum) verifySignatures(msg []byte, signatures []SafetySignature) error {
	if len(q.signers) != 3 || len(signatures) < 2 || len(signatures) > 3 {
		return ErrInvalidApproval
	}
	seen := make(map[string]bool, len(signatures))
	for _, sig := range signatures {
		key, ok := q.signers[sig.SignerID]
		if !ok || seen[sig.SignerID] || len(sig.Signature) != ed25519.SignatureSize || !ed25519.Verify(key, msg, sig.Signature) {
			return ErrInvalidApproval
		}
		seen[sig.SignerID] = true
	}
	return nil
}

// VerifySafetyApproval verifies an approval only; use Stop/Release for transitions.
func (q SafetyQuorum) VerifySafetyApproval(state AuthorityState, action SafetyAction, expectedEpoch Epoch, commandID, nonce string, signatures []SafetySignature) error {
	if action == SafetyActionRelease {
		return fmt.Errorf("%w: release requires activation-bound transition", ErrInvalidApproval)
	}
	return q.verify(state, action, expectedEpoch, commandID, nonce, nil, signatures)
}

type SafetyTransitionResult struct {
	State     AuthorityState
	CommandID string
}

// Stop authenticates a scoped command against the current epoch then advances SecurityEpoch exactly once.
func (q SafetyQuorum) Stop(state AuthorityState, expectedScope ScopeID, expectedEpoch Epoch, commandID, nonce string, signatures []SafetySignature) (SafetyTransitionResult, error) {
	if state.Scope != expectedScope {
		return SafetyTransitionResult{}, ErrInvalidApproval
	}
	if err := q.verify(state, SafetyActionStop, expectedEpoch, commandID, nonce, nil, signatures); err != nil {
		return SafetyTransitionResult{}, err
	}
	if state.Mode != ScopeActive {
		return SafetyTransitionResult{}, ErrInvalidApproval
	}
	stopped, err := applyEmergencyStop(state)
	if err != nil {
		return SafetyTransitionResult{}, err
	}
	return SafetyTransitionResult{State: stopped, CommandID: commandID}, nil
}

// Release is a separate authenticated transition. The approval binds the complete
// proposed activation, preventing arbitrary policy replacement or cross-command replay.
func (q SafetyQuorum) Release(state, activation AuthorityState, expectedScope ScopeID, expectedEpoch Epoch, commandID, nonce string, signatures []SafetySignature) (SafetyTransitionResult, error) {
	if !state.DatabaseAvailable {
		return SafetyTransitionResult{}, ErrDatabaseUnavailable
	}
	if err := state.Validate(); err != nil {
		return SafetyTransitionResult{}, fmt.Errorf("%w: invalid current state", ErrInvalidApproval)
	}
	if state.Scope != expectedScope || state.SecurityEpoch != expectedEpoch || state.Mode != ScopeSafeStop {
		return SafetyTransitionResult{}, ErrInvalidApproval
	}
	if !activation.DatabaseAvailable || activation.Mode != ScopeActive || activation.Scope != state.Scope || activation.SecurityEpoch <= state.SecurityEpoch || activation.ScopeActivationEpoch <= state.ScopeActivationEpoch {
		return SafetyTransitionResult{}, ErrInvalidApproval
	}
	if err := activation.Validate(); err != nil {
		return SafetyTransitionResult{}, fmt.Errorf("%w: invalid activation", ErrInvalidApproval)
	}
	next, err := state.SecurityEpoch.Next()
	if err != nil {
		return SafetyTransitionResult{}, err
	}
	if activation.SecurityEpoch != next {
		return SafetyTransitionResult{}, ErrInvalidApproval
	}
	digest, err := ActivationDigest(activation)
	if err != nil {
		return SafetyTransitionResult{}, err
	}
	if err := q.verify(state, SafetyActionRelease, expectedEpoch, commandID, nonce, &digest, signatures); err != nil {
		return SafetyTransitionResult{}, err
	}
	return SafetyTransitionResult{State: cloneAuthority(activation), CommandID: commandID}, nil
}
